script:
frappe.ui.form.on("Student Enrollment", {
    setup(frm) {
        set_invitation_code_filter(frm);
    },

    refresh(frm) {
        set_invitation_code_filter(frm);
    },

    course(frm) {
        frm.set_value("invitation_code", "");
        set_invitation_code_filter(frm);
    },

    invitation_code(frm) {
        validate_selected_invitation_code(frm);
    },
});


function set_invitation_code_filter(frm) {
    frm.set_query("invitation_code", () => {
        if (!frm.doc.course) {
            return {
                filters: [
                    ["Invitation Code", "name", "=", ""]
                ]
            };
        }

        return {
            filters: [
                ["Invitation Code", "course", "=", frm.doc.course],
                ["Invitation Code", "status", "=", "Available"],
                ["Invitation Code", "valid_until", ">=", frappe.datetime.get_today()]
            ]
        };
    });
}


function validate_selected_invitation_code(frm) {
    if (!frm.doc.invitation_code) {
        return;
    }

    frappe.db.get_doc("Invitation Code", frm.doc.invitation_code).then((invitation_code) => {
        const today = frappe.datetime.get_today();

        if (invitation_code.course !== frm.doc.course) {
            frm.set_value("invitation_code", "");
            frappe.msgprint(__("The selected Invitation Code does not belong to the selected Course."));
            return;
        }

        if (invitation_code.status !== "Available") {
            frm.set_value("invitation_code", "");
            frappe.msgprint(__("The selected Invitation Code is not available."));
            return;
        }

        if (invitation_code.valid_until && invitation_code.valid_until < today) {
            frm.set_value("invitation_code", "");
            frappe.msgprint(__("The selected Invitation Code has expired."));
        }
    });
}
